// 這些國家不在 COUNTRY_REGION 裡，會落回歐洲封建預設表（OCCUPATIONS_BY_ERA） - 但它們
// 沒有本土世襲貴族／宮廷傳統：美加澳紐是移民/殖民地建國（美國憲法更明文禁止封爵），
// 中南美洲與加勒比海諸國則是西班牙／葡萄牙／法／英殖民地史，也不是歐洲本土封建貴族。
// 不管哪個年代抽到，都不該套用 noble 類職業（宮廷重臣、世襲公爵…），
