// 每個國名對應「這個政治實體最早以這個名字/國界存在」的年份 - 輪迴鏈裡任何一世的年份
// 早於這裡列的年份，rollOne() 就不會把該國納入候選池，避免抽到「1200年的德國」這種錯置。
// 只收錄西元1800年後才出現的國家：更早成立、有長期延續性的國家（中國、日本、法國、
// 英國、西班牙、葡萄牙、衣索比亞、泰國、伊朗…）不列在這裡，視為整個1000-2010年區間都成立，
// 這也是絕大多數穿越/轉生題材處理「古老國家」的通行做法。俄羅斯、巴勒斯坦這類主權延續性
// 或政治地位有爭議的國家刻意不收錄，避免捲入爭議性的政治判斷。
