// 一世固定抽一條線走完（index.html 的 buildLifeBiographyHTML），童年埋的錨
// （一個人、一件物、一句話）會在中年、晚年被呼應。寫法見 .claude/skills/micro-story。
// 文字刻意保持時代與文化中性（不出現特定年代的器物），同一池服務 1000–2026 年、196 國；
// 地方風味由 {token} 佔位符 + FLAVOR_BY_REGION 在抽取時代入。
